insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'daily', 'Ertalabki 15 daqiqalik qisqa yig''ilishda', 'Ertalabki 15 daqiqalik qisqa yig''ilishda (Daily Standup) Admin, Sotuv, MMD va O''quv bo''limining bugungi asosiy rejalarini tekshirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'daily', 'Teacherlar nazorati', 'O''qituvchilarning darsga vaqtida kelgani, bir kun oldin Lesson Plan kiritgani, kunlik davomat qilingani va xonalar tozaligini Admin ma''lumoti asosida tekshirish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'daily', 'MMD nazorati', 'Instagram va Telegramda kunlik post/story joylanganini, video montajlar tayyorligini va kechagi postlar hisobotini qabul qilish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'daily', 'Sotuv va Admin nazorati', 'Kunlik qo''ng''iroqlar soni, har bir lidga komment yozilgani (izohsiz lid yo''qligi), Admin va Sotuv menejerining kunlik lidlar tahlili hamda qarzdorlar bo''yicha qilgan ishlarini tekshirish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'daily', 'Reception nazorati', 'Reception doimo toza va tartibli turganini (tartibsiz narsalar yo''qligini) hamda kunlik kassa tushumini ko''zdan kechirish.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'daily', 'Kun yakunida barcha xodimlar kunlik tasklarini', 'Kun yakunida barcha xodimlar kunlik tasklarini tekshirib tugatganini tasdiqlash.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'weekly', 'Haftalik jamoa yig''ilishi', 'Haftalik bo''lim boshliqlari bilan natijalar va rejalarni ko''rib chiqish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'weekly', 'Asosiy KPI nazorati', 'Sotuv, akademik, moliya va operatsion asosiy ko''rsatkichlarni haftalik tekshirish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'weekly', 'Strategik qarorlar va to''siqlar', 'Haftalik jamoa to''siqlarini (blockers) hal qilish va qarorlar qabul qilish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'monthly', 'Oylik P&L va biznes sog''lig''i', 'Oylik to''liq moliyaviy va biznes ko''rsatkichlar tahlilini o''tkazish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'monthly', 'Oylik KPI va bonus tasdiqlash', 'Xodimlar oylik KPI (Grade A-D) va bonus fondini ko''rib chiqib tasdiqlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('ceo', 'monthly', 'Oylik strategik maqsadlar', 'Kelgusi oy uchun kompaniya maqsadlari va ustuvorliklarni belgilash.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'daily', 'Ertalabki 15 daqiqalik qisqa yig''ilishda', 'Ertalabki 15 daqiqalik qisqa yig''ilishda (Daily Standup) Admin, Sotuv, MMD va O''quv bo''limining bugungi asosiy rejalarini tekshirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'daily', 'Teacherlar nazorati', 'O''qituvchilarning darsga vaqtida kelgani, bir kun oldin Lesson Plan kiritgani, kunlik davomat qilingani va xonalar tozaligini Admin ma''lumoti asosida tekshirish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'daily', 'MMD nazorati', 'Instagram va Telegramda kunlik post/story joylanganini, video montajlar tayyorligini va kechagi postlar hisobotini qabul qilish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'daily', 'Sotuv va Admin nazorati', 'Kunlik qo''ng''iroqlar soni, har bir lidga komment yozilgani (izohsiz lid yo''qligi), Admin va Sotuv menejerining kunlik lidlar tahlili hamda qarzdorlar bo''yicha qilgan ishlarini tekshirish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'daily', 'Reception nazorati', 'Reception doimo toza va tartibli turganini (tartibsiz narsalar yo''qligini) hamda kunlik kassa tushumini ko''zdan kechirish.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'daily', 'Kun yakunida barcha xodimlar kunlik tasklarini', 'Kun yakunida barcha xodimlar kunlik tasklarini tekshirib tugatganini tasdiqlash.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'weekly', 'Haftalik operatsion ko''rib chiqish', 'Barcha bo''limlar operatsion holatini va to''siqlarni haftalik ko''rib chiqish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'weekly', 'Asosiy KPI nazorati', 'Sotuv, akademik, moliya va operatsion asosiy ko''rsatkichlarni haftalik tekshirish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'weekly', 'Jamoa muvofiqlashtiruvi', 'Bo''lim boshliqlari bilan haftalik maqsadlarni muvofiqlashtirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'monthly', 'Oylik operatsion hisobot', 'Barcha bo''limlar oylik operatsion samaradorligi bo''yicha hisobot.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'monthly', 'Oylik KPI ko''rib chiqish', 'Bo''limlar oylik KPI natijalarini CEO bilan birga ko''rib chiqish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('coo', 'monthly', 'Oylik maqsadlarni muvofiqlashtirish', 'Kelgusi oy bo''lim maqsadlari va resurslarini muvofiqlashtirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Yangi lidlarga tezkor aloqaga chiqish (Speed-to-Lead <= 5–10 daqiqa)', 'Instagram, Telegram, qo''ng''iroq yoki markazga tashrif orqali tushgan har bir yangi murojaatga 5–10 daqiqa ichida qo''ng''iroq qilish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Kunlik qo''ng''iroqlar qilish', 'Kun davomida yangi lidlar, sinov darsiga yozilganlar va qayta aloqadagi mijozlarga sotuv skripti asosida belgilangan normada (kuniga kamida 40–60 ta) sifatli qo''ng''iroqlar qilish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Har kuni lidlar bilan bog''lanib kommentiga izoh yozib chiqish (komment bo''lishi shart)', 'Bog''lanilgan har bir lidning CRM / Google Sheets kartochkasiga suhbat natijasi, mijozning ingliz tili darajasi, o''qish maqsadi, bo''sh vaqti, e''tirozi va keyingi aloqa sanasi haqida aniq izoh (komment) yozib chiqish — birorta ham lid izohsiz (kommentsiz) qolmasligi shart!', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Lidlar ustida tahlil qilish (kunlik Admin yoki Office Manager bilan hamkorlikda)', 'Har kuni Admin (Office Manager) bilan birgalikda tushgan lidlar sifati, qaysi guruhlarda bo''sh joy borligi (14 kishilik xona limiti doirasida), sinov darsiga yozilganlar va guruhga joylashish ko''rsatkichlarini tahlil qilish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Sinov darsiga yozilganlarni tasdiqlash (Show-Up Confirmation)', 'Bugungi sinov darslariga yozilgan barcha nomzodlarga darsdan 2–3 soat oldin qo''ng''iroq qilib yoki xabar yuborib, dars vaqti va xonasini eslatish hamda kelishini tasdiqlash.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Sinov darsidan chiqqan o''quvchilarga sotuv qilish (Closing)', 'Sinov darsida qatnashgan o''quvchi va ota-onasi bilan dars tugashi bilanoq suhbatlashish, o''qituvchi xulosasini tushuntirish, e''tirozlarni yopish va 490,000 UZS oylik to''lovga shartnoma tuzish.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Kunlik Admin yoki Office Manager bilan hamkorlikda qarzdorlar bilan ishlash', 'Har kuni Admin (Office Manager) bilan birgalikda to''lov muddati kelgan va kechikkan qarzdor o''quvchilar ro''yxatini ko''rib chiqish, ularga va ota-onalariga qo''ng''iroq qilib to''lovni amalga oshirishni eslatish hamda natijasini jadvalga kiritish.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Eski va "o''ylab ko''raman" degan lidlar bilan qayta ishlash (Reactivation)', 'Avval murojaat qilib, hali o''qishni boshlamagan mijozlarga qo''ng''iroq qilib, yangi ochilayotgan guruhlar va 40 daqiqalik bepul support darslari imkoniyatini taklif etish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Tavsiya (Referral) orqali yangi lidlar yig''ish', 'Markazda mamnun o''qiyotgan talabalar va ularning ota-onalaridan do''stlarini taklif qilish bo''yicha kontaktlar olish.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'daily', 'Kunlik tasklarni tekshirib tugatish', 'Kun yakunida barcha kunlik vazifalarni (tasklarni) ko''zdan kechirish, har bir lidga komment yozilganini tekshirish, kunlik qo''ng''iroqlar va sotuvlar soni bo''yicha rahbariyatga hisobot topshirish.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'weekly', 'Jamoa sotuv natijalari', 'Sotuv jamoasining haftalik shartnoma va konversiya natijalarini ko''rib chiqish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'weekly', 'Haftalik lidlar voronkasi', 'Barcha kanallar bo''yicha lid-shartnoma voronkasini haftalik tahlil qilish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'weekly', 'Marketing bilan muvofiqlashtirish', 'MMD bilan haftalik lid sifati va kampaniyalar bo''yicha muvofiqlashtirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'monthly', 'Oylik sotuv-marketing hisoboti', 'Jamoaning oylik lid, shartnoma, CAC va ROMI ko''rsatkichlari bo''yicha hisobot.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('commercial_director', 'monthly', 'Oylik maqsad va reja', 'Kelgusi oy sotuv va marketing maqsadlari hamda byudjetini belgilash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Barcha 4 nafar', 'Barcha 4 nafar (va yangi) o''qituvchilarning darsga vaqtida kelgani hamda dars materiallari shayligini ertalabki smena oldidan tekshirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'O''qituvchilar tomonidan bir kun oldin kiritilgan', 'O''qituvchilar tomonidan bir kun oldin kiritilgan Lesson Plan (dars rejalari) sifatini ko''rib chiqish va tasdiqlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Kuniga kamida 1–2 ta guruh darsiga kirib kuzatish', 'Kuniga kamida 1–2 ta guruh darsiga kirib kuzatish (Lesson Observation — STT >= 70% va interaktivlikni baholash) hamda o''qituvchiga feedback berish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Yangi kelgan murakkab darajadagi o''quvchilarning', 'Yangi kelgan murakkab darajadagi o''quvchilarning Placement Test (og''zaki suhbat) natijalarini tasdiqlash va mos guruhga yo''naltirish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'O''qituvchilarning 40 daqiqalik Support darslari', 'O''qituvchilarning 40 daqiqalik Support darslari o''tilishini va uy vazifalari vaqtida tekshirilishini nazorat qilish.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Kunlik tasklarni tekshirib tugatish va akademik', 'Kunlik tasklarni tekshirib tugatish va akademik sifat bo''yicha kunlik qaydnomani to''ldirish.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Kunlik davomat jurnalidan darsga kelmagan barcha', 'Kunlik davomat jurnalidan darsga kelmagan barcha o''quvchilar ro''yxatini olish va Admin bilan birga sababini aniqlash.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Ketma-ket 2 ta dars qoldirgan yoki o''zlashtirishi <', 'Ketma-ket 2 ta dars qoldirgan yoki o''zlashtirishi < 70% ga tushgan o''quvchilar (Red Flags) bilan shaxsan va ota-onasi bilan bog''lanish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Yangi qo''shilgan o''quvchilarning dastlabki 14 va 30', 'Yangi qo''shilgan o''quvchilarning dastlabki 14 va 30 kunlik moslashuvini (Onboarding) tekshirish va darsdan qoniqishini so''rash.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'O''zlashtirishi past o''quvchilarni o''qituvchining 40', 'O''zlashtirishi past o''quvchilarni o''qituvchining 40 daqiqalik Support darsiga yozish va ularning qatnashganini tekshirish.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Ketish ehtimoli bo''lgan o''quvchilar bilan', 'Ketish ehtimoli bo''lgan o''quvchilar bilan individual suhbatlashib, muammosini hal qilish (guruh yoki vaqtni almashtirish, qo''shimcha dars berish) va oylik churnni kamaytirish.', 10);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'daily', 'Kunlik tasklarni tekshirib tugatish va saqlab', 'Kunlik tasklarni tekshirib tugatish va saqlab qolingan o''quvchilar bo''yicha hisobot kiritish.', 11);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'weekly', 'Lesson Observation (dars kuzatuvi)', 'Haftalik o''qituvchilar darsiga kirib STT (>=70%) va interaktivlikni baholab feedback berish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'weekly', 'Lesson Plan sifat nazorati', 'Haftalik barcha kiritilgan Lesson Plan sifatini tekshirib tasdiqlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'weekly', 'Red Flag va churn tahlili', 'Haftalik xavf ostidagi va ketish ehtimoli bo''lgan o''quvchilar bilan ishlash.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'weekly', 'Onboarding (14/30 kun) tekshiruvi', 'Yangi o''quvchilarning dastlabki moslashuvini haftalik tekshirish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'monthly', 'Oylik akademik sifat hisoboti', 'O''zlashtirish, davomat va o''qituvchilar KPI bo''yicha oylik hisobot tayyorlash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'monthly', 'Oylik churn va retention tahlili', 'Oylik o''quvchilar saqlanishi (retention) va ketish sabablarini tahlil qilish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('academic_director', 'monthly', 'O''qituvchilar rivojlanishi (CAP/PIP)', 'Oylik o''qituvchilar bilan kasbiy rivojlanish rejasini muvofiqlashtirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Darsga vaqtida kelish', 'Birinchi dars boshlanishidan kamida 15–20 daqiqa oldin o''quv markazida va sinfxonada bo''lish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Materiallarni darsdan oldin tayyorlab qo''yish', 'Darsliklar, tarqatma materiallar (handoutlar), markerlar, doska va audio/video fayllarni dars boshlanishidan oldin 14 nafar o''quvchi sig''imiga moslab to''liq tayyorlab qo''yish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Bir kun oldin Lesson Plan kiritish', 'Ertangi kungi barcha guruhlar uchun dars rejasini (Lesson Plan) bir kun oldin soat 18:00 gacha elektron baza / tizimga kiritib qo''yish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Kunlik gruppalarni davomat qilish', 'Har bir darsning dastlabki 10 daqiqasida guruh davomatini elektron jurnal / CRM (Google Sheets) ga kiritish hamda darsga kelmagan yoki kechikkan o''quvchilarni darhol Administrative Manager (Reception) ga xabar qilish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Interaktiv dars o''tish (STT >= 70%)', '80–90 daqiqalik darsni 100% ingliz tili muhitida (English-only) va o''quvchilar faolligida (Student Talking Time kamida 70%) yuqori energiya bilan o''tkazish.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Uyga vazifalarni (Homework) tekshirish', 'O''quvchilarning uyga vazifalarini va mashq daftarlarini 24 soat ichida tekshirib, har bir o''quvchiga xatolari bo''yicha aniq feedback berish.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Sinov darsidagi (Trial Lesson) o''quvchilarga xulosa berish', 'Guruhga sinov darsiga kirgan yangi o''quvchiga alohida e''tibor qaratish va dars tugagach 15 daqiqa ichida uning darajasi haqida Sotuv menejeri hamda Adminga xulosa berish.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Qoloq o''quvchilarni 40 daqiqalik Support darsiga yozish', 'Mavzuni o''zlashtirishda qiynalgan yoki dars qoldirgan o''quvchilarni aniqlab, haftalik 40 daqiqalik bepul qo''shimcha darsga (Support Lesson) biriktirish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Xavf ostidagi o''quvchilar (Red Flags) haqida xabar berish', 'Ketma-ket 2 marta darsga kelmagan yoki motivatsiyasi tushgan o''quvchilar ro''yxatini darsdan so''ng Admin va Bosh metodistga topshirish.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Xona tozaligiga e''tibor berish', 'Har bir dars tugagach doskani toza qilib o''chirish, 14 ta stul va partani tartibga keltirish, xonada qog''oz yoki chiqindi qolmasligini nazorat qilish hamda xonani shamollatish.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'daily', 'Kunlik tasklarni tekshirib tugatish', 'Ish kuni yakunida barcha guruhlar davomati kiritilgani, uy vazifalari tekshirilgani, ertangi Lesson Plan yuklangani va shaxsiy kunlik vazifalar (tasklar) 100% bajarilganini tekshirib tugatish.', 10);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'weekly', 'Haftalik Lesson Plan va materiallar', 'Kelgusi haftaning barcha darslari uchun Lesson Plan va materiallarni dushanba oldidan tayyorlab, bazaga yuklash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'weekly', 'Yo''nalish o''qituvchilarini kuzatish', 'O''z yo''nalishidagi o''qituvchilar darsiga kirib, sifat va interaktivlikni haftalik baholash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'weekly', 'Support darsi jadvali', 'Haftalik 40 daqiqalik Support darslari jadvalini tuzib, qoloq o''quvchilarni biriktirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'weekly', 'Haftalik progress va Red Flag', 'Yo''nalish o''quvchilarining davomati va o''zlashtirishini ko''rib, Red Flaglarni metodistga xabar qilish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'monthly', 'Yo''nalish oylik hisoboti', 'O''z yo''nalishi bo''yicha oylik o''zlashtirish, davomat va o''qituvchilar natijalarini jamlash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'monthly', 'Oylik syllabus rejasi', 'Yo''nalish guruhlari uchun kelgusi oy syllabus va mavzular rejasini tasdiqlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('head_teacher', 'monthly', 'O''qituvchilar rivojlanishi', 'Yo''nalish o''qituvchilari bilan oylik kasbiy rivojlanish (CAP) suhbatini o''tkazish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Darsga vaqtida kelish', 'Birinchi dars boshlanishidan kamida 15–20 daqiqa oldin o''quv markazida va sinfxonada bo''lish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Materiallarni darsdan oldin tayyorlab qo''yish', 'Darsliklar, tarqatma materiallar (handoutlar), markerlar, doska va audio/video fayllarni dars boshlanishidan oldin 14 nafar o''quvchi sig''imiga moslab to''liq tayyorlab qo''yish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Bir kun oldin Lesson Plan kiritish', 'Ertangi kungi barcha guruhlar uchun dars rejasini (Lesson Plan) bir kun oldin soat 18:00 gacha elektron baza / tizimga kiritib qo''yish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Kunlik gruppalarni davomat qilish', 'Har bir darsning dastlabki 10 daqiqasida guruh davomatini elektron jurnal / CRM (Google Sheets) ga kiritish hamda darsga kelmagan yoki kechikkan o''quvchilarni darhol Administrative Manager (Reception) ga xabar qilish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Interaktiv dars o''tish (STT >= 70%)', '80–90 daqiqalik darsni 100% ingliz tili muhitida (English-only) va o''quvchilar faolligida (Student Talking Time kamida 70%) yuqori energiya bilan o''tkazish.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Uyga vazifalarni (Homework) tekshirish', 'O''quvchilarning uyga vazifalarini va mashq daftarlarini 24 soat ichida tekshirib, har bir o''quvchiga xatolari bo''yicha aniq feedback berish.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Sinov darsidagi (Trial Lesson) o''quvchilarga xulosa berish', 'Guruhga sinov darsiga kirgan yangi o''quvchiga alohida e''tibor qaratish va dars tugagach 15 daqiqa ichida uning darajasi haqida Sotuv menejeri hamda Adminga xulosa berish.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Qoloq o''quvchilarni 40 daqiqalik Support darsiga yozish', 'Mavzuni o''zlashtirishda qiynalgan yoki dars qoldirgan o''quvchilarni aniqlab, haftalik 40 daqiqalik bepul qo''shimcha darsga (Support Lesson) biriktirish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Xavf ostidagi o''quvchilar (Red Flags) haqida xabar berish', 'Ketma-ket 2 marta darsga kelmagan yoki motivatsiyasi tushgan o''quvchilar ro''yxatini darsdan so''ng Admin va Bosh metodistga topshirish.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Xona tozaligiga e''tibor berish', 'Har bir dars tugagach doskani toza qilib o''chirish, 14 ta stul va partani tartibga keltirish, xonada qog''oz yoki chiqindi qolmasligini nazorat qilish hamda xonani shamollatish.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'daily', 'Kunlik tasklarni tekshirib tugatish', 'Ish kuni yakunida barcha guruhlar davomati kiritilgani, uy vazifalari tekshirilgani, ertangi Lesson Plan yuklangani va shaxsiy kunlik vazifalar (tasklar) 100% bajarilganini tekshirib tugatish.', 10);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'weekly', 'Haftalik Lesson Plan va materiallar', 'Kelgusi haftaning barcha darslari uchun Lesson Plan va tarqatma materiallarni dushanba oldidan tayyorlab, bazaga yuklab qo''yish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'weekly', 'Support darsi va qoloqlar', 'Hafta davomida o''zlashtirishi past o''quvchilarni 40 daqiqalik Support darsiga yozib, qatnashganini yakunda tekshirish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'weekly', 'Speaking Club / Quiz o''tkazish', 'Haftalik Speaking Club, Zakovat yoki Movie Day uchun savol-materiallarni tayyorlab, tadbirni o''tkazish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'weekly', 'Haftalik progress va Red Flag', 'Guruhlar davomati va o''zlashtirishini ko''rib chiqib, xavf ostidagi (Red Flag) o''quvchilarni Bosh metodistga xabar qilish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'monthly', 'Oylik mavzu rejasi (Syllabus)', 'Kelgusi oy uchun kurs syllabusiga muvofiq mavzular taqsimotini tayyorlash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'monthly', 'Oylik Progress Test', 'Guruhlarda oylik oraliq (progress) testini o''tkazib, natijalarni bazaga kiritish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('teacher', 'monthly', 'O''z KPI va rivojlanish', 'Oylik KPI (STT, davomat, natija) hisobotini topshirish va kasbiy rivojlanish (CAP) bo''yicha suhbat.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('assistant', 'daily', 'Darsga yordam tayyorligi', 'O''qituvchiga dars oldidan materiallar, texnika va xona tayyorligini ta''minlashda yordam berish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('assistant', 'daily', 'Davomat va kechikkanlar', 'Dars davomatini kiritishda yordam berish va kechikkan o''quvchilarni Adminga xabar qilish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('assistant', 'daily', 'Uy vazifalarni yig''ish', 'O''quvchilardan uy vazifalarini yig''ib, o''qituvchiga tekshirish uchun topshirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('assistant', 'weekly', 'Support darsiga yordam', 'Haftalik 40 daqiqalik Support darslarida o''qituvchiga yordam berish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('assistant', 'weekly', 'Materiallar zaxirasi', 'Haftalik tarqatma materiallar, marker va daftarlar zaxirasini to''ldirish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('assistant', 'monthly', 'Oylik rivojlanish suhbati', 'Oylik o''qituvchilik ko''nikmalari bo''yicha metodistdan feedback olish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Kunlik Instagram va Telegram postlarni tekshirib hisobot topshirish', 'Har kuni ertalab (09:00–09:30) kechagi chiqqan Instagram va Telegram postlarning qamrovi (reach), ko''rishlar soni, izohlar, saqlashlar va reklama orqali kelgan lidlar sonini tekshirib, rahbariyatga kunlik hisobot topshirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Instagram va Telegram kunlik post yoki story joylash (har kuni kontent qilinishi kerak, kamida story)', 'Har kuni uzluksiz ravishda kamida 5–7 ta jonli Story (dars jarayonlari, o''quvchilar natijasi, viktorina/so''rovnomalar, markaz hayoti) va kontent-reja bo''yicha kunlik post/Reels joylash — sahifalar bir kun ham kontentsiz qolmasligi shart.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Jonli foto va video syomka qilish', 'Har kuni 5 ta o''quv xonasidagi interaktiv dars jarayonlari, o''qituvchilarning dars o''tish uslubi, 40 daqiqalik support darslari va o''quvchilarning ingliz tilida gaplashayotgan lavhalarini tasvirga olish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Video montaj qilish', 'Tasvirga olingan Reels, YouTube Shorts va video-sharhlarni sifatli montaj qilish (dinamik kadrlar, subtitrlar, sifatli ovoz, rang korreksiyasi va Persons LC logotipi bilan tayyorlash).', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'E''lon qilishdan oldin xatosizlikni (Poka-Yoke) tekshirish', 'Joylanayotgan har bir post, video va storyda imlo xatolari yo''qligini, kurs narxi (490,000 UZS), guruh sig''imi (14 talaba), telefon raqami va manzil to''g''ri yozilganini tekshirish.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Target reklamalarni (Meta Ads) nazorat qilish', 'Faol reklama kampaniyalarining byudjeti, lid tannarxi (CPL) va reklama kreativlarining uzluksiz ishlayotganini tekshirish.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Direct va izohlardagi (kommentlardagi) murojaatlarni Sotuvga uzatish', 'Instagram Direct, postlar ostidagi izohlar va Telegram botga kelgan yangi so''rovlarni 5 daqiqa ichida Sotuv menejeriga va CRM bazasiga o''tkazish.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'O''quvchilardan natija va fikrlar (Social Proof) olish', 'Imtihondan yuqori ball olgan yoki sinov darsidan mamnun bo''lgan o''quvchilardan qisqa intervyu va video-otzivlar yozib olish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Ertangi kun kontentini tayyorlab qo''yish', 'Ertasi kuni ertalabdan chiqadigan storylar ketma-ketligi va asosiy post/video tayyor holatda ekanini kechqurun tekshirib qo''yish.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'daily', 'Kunlik tasklarni tekshirib tugatish', 'Ish kuni yakunida kontent-rejadagi barcha kunlik vazifalar, montajlar va hisobotlar to''liq bajarilganini tekshirib tugatish.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'weekly', 'Haftalik kontent-reja', 'Kelgusi haftaning Instagram/Telegram post, Reels va story rejasini tayyorlab tasdiqlatish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'weekly', 'Reels / montaj to''plami', 'Haftada kamida bir nechta sifatli Reels va video montaj tayyorlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'weekly', 'Reklama natijalari (CPL)', 'Faol Meta Ads kampaniyalarining CPL, qamrov va lid sonini haftalik tahlil qilib hisobot berish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'weekly', 'Social Proof yig''ish', 'Haftalik o''quvchi natijalari va video-otzivlardan kontent tayyorlash.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'monthly', 'Oylik marketing hisoboti', 'Oylik qamrov, follower o''sishi, lid soni va CAC bo''yicha hisobot tayyorlash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('mmd', 'monthly', 'Oylik kontent strategiyasi', 'Kelgusi oy uchun kontent yo''nalishi va reklama kampaniya rejasini tuzish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Yangi lidlarga tezkor aloqaga chiqish (Speed-to-Lead <= 5–10 daqiqa)', 'Instagram, Telegram, qo''ng''iroq yoki markazga tashrif orqali tushgan har bir yangi murojaatga 5–10 daqiqa ichida qo''ng''iroq qilish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Kunlik qo''ng''iroqlar qilish', 'Kun davomida yangi lidlar, sinov darsiga yozilganlar va qayta aloqadagi mijozlarga sotuv skripti asosida belgilangan normada (kuniga kamida 40–60 ta) sifatli qo''ng''iroqlar qilish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Har kuni lidlar bilan bog''lanib kommentiga izoh yozib chiqish (komment bo''lishi shart)', 'Bog''lanilgan har bir lidning CRM / Google Sheets kartochkasiga suhbat natijasi, mijozning ingliz tili darajasi, o''qish maqsadi, bo''sh vaqti, e''tirozi va keyingi aloqa sanasi haqida aniq izoh (komment) yozib chiqish — birorta ham lid izohsiz (kommentsiz) qolmasligi shart!', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Lidlar ustida tahlil qilish (kunlik Admin yoki Office Manager bilan hamkorlikda)', 'Har kuni Admin (Office Manager) bilan birgalikda tushgan lidlar sifati, qaysi guruhlarda bo''sh joy borligi (14 kishilik xona limiti doirasida), sinov darsiga yozilganlar va guruhga joylashish ko''rsatkichlarini tahlil qilish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Sinov darsiga yozilganlarni tasdiqlash (Show-Up Confirmation)', 'Bugungi sinov darslariga yozilgan barcha nomzodlarga darsdan 2–3 soat oldin qo''ng''iroq qilib yoki xabar yuborib, dars vaqti va xonasini eslatish hamda kelishini tasdiqlash.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Sinov darsidan chiqqan o''quvchilarga sotuv qilish (Closing)', 'Sinov darsida qatnashgan o''quvchi va ota-onasi bilan dars tugashi bilanoq suhbatlashish, o''qituvchi xulosasini tushuntirish, e''tirozlarni yopish va 490,000 UZS oylik to''lovga shartnoma tuzish.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Kunlik Admin yoki Office Manager bilan hamkorlikda qarzdorlar bilan ishlash', 'Har kuni Admin (Office Manager) bilan birgalikda to''lov muddati kelgan va kechikkan qarzdor o''quvchilar ro''yxatini ko''rib chiqish, ularga va ota-onalariga qo''ng''iroq qilib to''lovni amalga oshirishni eslatish hamda natijasini jadvalga kiritish.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Eski va "o''ylab ko''raman" degan lidlar bilan qayta ishlash (Reactivation)', 'Avval murojaat qilib, hali o''qishni boshlamagan mijozlarga qo''ng''iroq qilib, yangi ochilayotgan guruhlar va 40 daqiqalik bepul support darslari imkoniyatini taklif etish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Tavsiya (Referral) orqali yangi lidlar yig''ish', 'Markazda mamnun o''qiyotgan talabalar va ularning ota-onalaridan do''stlarini taklif qilish bo''yicha kontaktlar olish.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'daily', 'Kunlik tasklarni tekshirib tugatish', 'Kun yakunida barcha kunlik vazifalarni (tasklarni) ko''zdan kechirish, har bir lidga komment yozilganini tekshirish, kunlik qo''ng''iroqlar va sotuvlar soni bo''yicha rahbariyatga hisobot topshirish.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'weekly', 'Haftalik lidlar voronkasi', 'Haftalik yangi lid, sinov darsi, shartnoma va konversiya ko''rsatkichlarini tahlil qilish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'weekly', 'Eski lidlarni qayta faollashtirish', 'Haftalik ''o''ylab ko''raman'' degan lidlar bilan qayta ishlash (Reactivation).', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'weekly', 'Qarzdorlar bilan ishlash', 'Haftalik qarzdor o''quvchilar ro''yxatini ko''rib, to''lovlarni undirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'weekly', 'Sotuv skripti va e''tirozlar', 'Eng ko''p uchragan e''tirozlarni ko''rib chiqib, sotuv skriptini yangilash.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'monthly', 'Oylik sotuv rejasi va maqsad', 'Oylik shartnoma va tushum maqsadini belgilash va o''tgan oy natijasini tahlil qilish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('sales_manager', 'monthly', 'Oylik konversiya hisoboti', 'Lid->shartnoma konversiyasi va kanallar samaradorligi bo''yicha hisobot.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Markazni vaqtida ochish va ishga shaylash', 'Darslar boshlanishidan 30 daqiqa oldin (08:30 da) markazga kelib, eshiklarni ochish, chiroqlar, konditsioner/isitish tizimi, kompyuter, printer va kassa jihozlarini ishga tushirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Reception tozaligiga har kuni nazorat qilish (tartibsiz turmasligi kerak)', 'Qabulxona (Reception) stoli va atrofini kun davomida doimiy ozoda va tartibli saqlash — stol ustida ortiqcha qog''ozlar, tartibsiz hujjatlar, chashkalar yoki shaxsiy buyumlar turmasligi shart.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', '5 ta sinfxona va kutish zalining tozaligini tekshirish', 'Darslar boshlanishidan oldin va smenalar orasida barcha 5 ta xonaning (har biri 14 talaba sig''imli) tozaligi, parta-stullar tekisligi, doskalar artilganligi, markerlar borligi va xona havosi yangilanganini nazorat qilish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'O''quvchilar va mehmonlarni yuqori madaniyat bilan kutib olish', 'Markazga kirib kelgan har bir o''quvchi, ota-ona va sinov darsiga kelgan mijozni ochiq chehra bilan kutib olish, ro''yxatga olish va tegishli xonaga yo''naltirish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Kunlik guruhlar davomatini va o''qituvchilar intizomini nazorat qilish', 'O''qituvchilarning darsga vaqtida kelganini, bir kun oldin Lesson Plan kiritganini va darsning 10-daqiqasigacha davomat qilinganini tekshirish; darsga kelmagan o''quvchilarning ota-onalariga 15 daqiqa ichida qo''ng''iroq qilib sababini aniqlash.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Sotuv menejeri bilan hamkorlikda kunlik lidlar ustida tahlil qilish', 'Har kuni Sotuv menejeri bilan yangi kelgan lidlar, sinov darsiga yozilganlar, Placement Test (daraja aniqlash testi) topshirganlar va ularni mos guruhlarga (14 kishilik kvota bo''yicha) joylashtirish ustida ishlash.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Shartnomalar tuzish va 490,000 UZS o''quv to''lovlarini qabul qilish', 'Yangi o''quvchilar bilan shartnoma imzolash, oylik 490,000 UZS to''lovlarni (naqd, terminal, Click/Payme) qabul qilish, chek berish va to''lovni shu zahoti CRM / kassa jadvaliga kiritish.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Sotuv menejeri bilan hamkorlikda qarzdorlar bilan ishlash', 'Har kuni to''lov muddati kelgan va kechikkan qarzdor o''quvchilar ro''yxatini shakllantirish, Sotuv menejeri bilan birgalikda o''quvchi hamda ota-onalarni ogohlantirish va qarzdorliklarni undirish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', '40 daqiqalik Support darslari jadvali va xonalarini muvofiqlashtirish', 'O''zlashtirishi past yoki dars qoldirgan o''quvchilar uchun o''qituvchilar o''tadigan 40 daqiqalik qo''shimcha darslarga bo''sh xona ajratish va o''quvchilar kelishini nazorat qilish.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Dars materiallari va xo''jalik jihozlarini ta''minlash', 'O''qituvchilar uchun kerakli tarqatma materiallar (print/nusxa ko''chirish), qog''oz, marker, ichimlik suvi va gigiyena vositalari doimo yetarli bo''lishini ta''minlash.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Kunlik tasklarni tekshirib tugatish, kassani yopish va binoni topshirish', 'Soat 20:30 da kunlik kassa kirim-chiqimlarini sanab Z-hisobot chiqarish, kunlik barcha tasklarni tekshirib tugatish, Reception va xonalar tozaligini farroshdan qabul qilib olish, barcha elektr jihozlarini o''chirib filialni yopish.', 10);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Barcha xodimlarning', 'Barcha xodimlarning (o''qituvchilar uchun haftasiga 36 soat, ma''muriy xodimlar uchun 40 soat) ishga vaqtida kelishini va kunlik davomatini tekshirish.', 11);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Bo''sh ish o''rinlari', 'Bo''sh ish o''rinlari (IELTS 7.0+ / CEFR C1 o''qituvchilar, sotuv va ma''muriy xodimlar) uchun nomzodlar rezyumelarini saralash, suhbat va demo-darslarni tashkil etish.', 12);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Yangi ishga kirgan xodimlarning 14 kunlik moslashuv', 'Yangi ishga kirgan xodimlarning 14 kunlik moslashuv (Onboarding) rejasini va mehnat shartnomasi hujjatlarini (2023-yilgi Mehnat Kodeksiga muvofiq) yuritish.', 13);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Xodimlarning oylik KPI ko''rsatkichlari', 'Xodimlarning oylik KPI ko''rsatkichlari (Grade A–D) va kasbiy rivojlanish rejalarini (CAP / PIP) bo''lim boshliqlari bilan birga muvofiqlashtirish.', 14);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Kunlik tasklarni tekshirib tugatish va jamoa ichki', 'Kunlik tasklarni tekshirib tugatish va jamoa ichki muhiti bo''yicha Bosh direktorga axborot berish.', 15);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Ertalab darslar boshlangunga qadar', 'Ertalab darslar boshlangunga qadar (08:00–08:45) Reception, koridor va barcha 5 ta o''quv xonasini namli tozalash, changlarni artish va chiqindi qutilarini bo''shatish.', 16);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Smenalar orasida', 'Smenalar orasida (tushlik va kechki darslar oldidan) Reception hamda xonalar tozaligini yangilab chiqish, pol va doskalarni tozalash.', 17);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Sanuzel (hojatxona) tozaligini kuniga kamida 3', 'Sanuzel (hojatxona) tozaligini kuniga kamida 3 marta tekshirish, suyuq sovun, qog''oz va antiseptik vositalarni to''ldirib qo''yish.', 18);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'daily', 'Kechki darslar tugagach', 'Kechki darslar tugagach (20:30 da) barcha xonalarni to''liq yig''ishtirib, Administrative Manager ko''rigidan o''tkazish.', 19);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'weekly', 'Haftalik davomat va intizom', 'Barcha xodimlarning haftalik davomati va ish soatlarini jamlab tekshirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'weekly', 'Kassa va to''lovlar solishtiruvi', 'Haftalik kassa kitobi, Z-hisobot va to''lovlar solishtiruvini yakunlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'weekly', 'Xo''jalik zaxira inventari', 'Haftalik gigiyena, kanstovar va xo''jalik mollari zaxirasini tekshirib, kam qolganini xarid qilish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'weekly', 'Onboarding hujjatlari', 'Yangi xodimlar uchun 14 kunlik moslashuv va shartnoma hujjatlarini yuritish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'monthly', 'Oylik hujjat va shartnomalar auditi', 'Barcha mehnat shartnomalari va kadrlar hujjatlarini oylik tekshirish (Mehnat Kodeksiga muvofiq).', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'monthly', 'Oylik xo''jalik xarajatlari', 'Oylik ijara, kommunal va xo''jalik xarajatlarini jamlab hisobot berish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('admin_manager', 'monthly', 'Oylik vakansiya va ishga olish', 'Ochiq vakansiyalar holati, nomzodlar va ishga olish rejasini ko''rib chiqish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Markazni vaqtida ochish va ishga shaylash', 'Darslar boshlanishidan 30 daqiqa oldin (08:30 da) markazga kelib, eshiklarni ochish, chiroqlar, konditsioner/isitish tizimi, kompyuter, printer va kassa jihozlarini ishga tushirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Reception tozaligiga har kuni nazorat qilish (tartibsiz turmasligi kerak)', 'Qabulxona (Reception) stoli va atrofini kun davomida doimiy ozoda va tartibli saqlash — stol ustida ortiqcha qog''ozlar, tartibsiz hujjatlar, chashkalar yoki shaxsiy buyumlar turmasligi shart.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', '5 ta sinfxona va kutish zalining tozaligini tekshirish', 'Darslar boshlanishidan oldin va smenalar orasida barcha 5 ta xonaning (har biri 14 talaba sig''imli) tozaligi, parta-stullar tekisligi, doskalar artilganligi, markerlar borligi va xona havosi yangilanganini nazorat qilish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'O''quvchilar va mehmonlarni yuqori madaniyat bilan kutib olish', 'Markazga kirib kelgan har bir o''quvchi, ota-ona va sinov darsiga kelgan mijozni ochiq chehra bilan kutib olish, ro''yxatga olish va tegishli xonaga yo''naltirish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Kunlik guruhlar davomatini va o''qituvchilar intizomini nazorat qilish', 'O''qituvchilarning darsga vaqtida kelganini, bir kun oldin Lesson Plan kiritganini va darsning 10-daqiqasigacha davomat qilinganini tekshirish; darsga kelmagan o''quvchilarning ota-onalariga 15 daqiqa ichida qo''ng''iroq qilib sababini aniqlash.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Sotuv menejeri bilan hamkorlikda kunlik lidlar ustida tahlil qilish', 'Har kuni Sotuv menejeri bilan yangi kelgan lidlar, sinov darsiga yozilganlar, Placement Test (daraja aniqlash testi) topshirganlar va ularni mos guruhlarga (14 kishilik kvota bo''yicha) joylashtirish ustida ishlash.', 5);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Shartnomalar tuzish va 490,000 UZS o''quv to''lovlarini qabul qilish', 'Yangi o''quvchilar bilan shartnoma imzolash, oylik 490,000 UZS to''lovlarni (naqd, terminal, Click/Payme) qabul qilish, chek berish va to''lovni shu zahoti CRM / kassa jadvaliga kiritish.', 6);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Sotuv menejeri bilan hamkorlikda qarzdorlar bilan ishlash', 'Har kuni to''lov muddati kelgan va kechikkan qarzdor o''quvchilar ro''yxatini shakllantirish, Sotuv menejeri bilan birgalikda o''quvchi hamda ota-onalarni ogohlantirish va qarzdorliklarni undirish.', 7);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', '40 daqiqalik Support darslari jadvali va xonalarini muvofiqlashtirish', 'O''zlashtirishi past yoki dars qoldirgan o''quvchilar uchun o''qituvchilar o''tadigan 40 daqiqalik qo''shimcha darslarga bo''sh xona ajratish va o''quvchilar kelishini nazorat qilish.', 8);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Dars materiallari va xo''jalik jihozlarini ta''minlash', 'O''qituvchilar uchun kerakli tarqatma materiallar (print/nusxa ko''chirish), qog''oz, marker, ichimlik suvi va gigiyena vositalari doimo yetarli bo''lishini ta''minlash.', 9);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'daily', 'Kunlik tasklarni tekshirib tugatish, kassani yopish va binoni topshirish', 'Soat 20:30 da kunlik kassa kirim-chiqimlarini sanab Z-hisobot chiqarish, kunlik barcha tasklarni tekshirib tugatish, Reception va xonalar tozaligini farroshdan qabul qilib olish, barcha elektr jihozlarini o''chirib filialni yopish.', 10);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'weekly', 'Haftalik operatsion ko''rsatkichlar', 'Xonalar bandligi, davomat va operatsion muammolarni haftalik ko''rib chiqish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'weekly', 'Jarayonlarni optimallashtirish', 'Haftalik takrorlanadigan muammolarni aniqlab, jarayon yaxshilash taklifini tayyorlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'monthly', 'Oylik operatsion hisobot', 'Oylik xonalar bandligi, sig''im va operatsion samaradorlik hisobotini tayyorlash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('operations_manager', 'monthly', 'Oylik ta''minot va jihozlar', 'Jihozlar holati va ta''mir/yangilash ehtiyojlarini oylik ko''rib chiqish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'daily', 'Andijon shahridagi hamkor maktablar va ta''lim', 'Andijon shahridagi hamkor maktablar va ta''lim muassasalari bilan bog''lanib, targ''ibot uchrashuvlari va olimpiadalar jadvalini kelishish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'daily', 'Haftalik "Speaking Club"', 'Haftalik "Speaking Club", "Zakovat / Quiz", "Movie Day" va debat tadbirlarining ssenariysi, savollari va xona jihozlarini tayyorlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'daily', 'Tadbirlar haqidagi e''lonlarni MMD bo''limi bilan', 'Tadbirlar haqidagi e''lonlarni MMD bo''limi bilan birgalikda Telegram va Instagramda yoritish hamda o''quvchilarni ro''yxatga olish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'daily', 'Tadbirlarga o''quvchilar o''z do''stlarini', 'Tadbirlarga o''quvchilar o''z do''stlarini (tashqi mehmonlarni) olib kelishini tashkil etish va kelgan mehmonlar kontaktini Sotuv menejeriga topshirish (har bir kontaktga komment yozilishi uchun).', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'daily', 'Kunlik tasklarni tekshirib tugatish va tadbir', 'Kunlik tasklarni tekshirib tugatish va tadbir natijalari hisobotini topshirish.', 4);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'weekly', 'Haftalik tadbir ssenariysi', 'Haftalik Speaking Club, Quiz yoki Movie Day tadbirini tashkil etib o''tkazish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'weekly', 'Tadbir e''lonlari (MMD bilan)', 'Haftalik tadbirlar e''lonini MMD bilan birga Instagram/Telegramda yoritish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'weekly', 'Referral kontaktlari', 'Tadbirlardan kelgan mehmonlar kontaktlarini Sotuv menejeriga topshirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'monthly', 'Oylik tadbirlar rejasi', 'Kelgusi oy uchun tadbirlar kalendarini tuzish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('event_manager', 'monthly', 'Oylik tadbirlar natijasi', 'Tadbirlardan kelgan lid va qatnashuv bo''yicha oylik hisobot tayyorlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'daily', 'Har kuni Admin', 'Har kuni Admin (Reception) tomonidan qabul qilingan 490,000 UZS o''quv to''lovlari (naqd, terminal, Click/Payme) va Z-hisobotlarni kassa kitobi bilan solishtirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'daily', 'Admin va Sotuv menejeri bilan birgalikda qarzdor', 'Admin va Sotuv menejeri bilan birgalikda qarzdor o''quvchilar to''lovlari tushishini moliyaviy nazorat qilish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'daily', 'Markazning kunlik va oylik ruxsat etilgan xarajatlarini', 'Markazning kunlik va oylik ruxsat etilgan xarajatlarini (ijara, kommunal, reklama byudjeti, xo''jalik xaridi) hisobga olish va hujjatlarini yuritish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'daily', 'Kunlik tasklarni tekshirib tugatish va Bosh', 'Kunlik tasklarni tekshirib tugatish va Bosh direktorga P&L (Foyda va Zarar) hamda Cash Flow (Pul oqimi) hisobotini taqdim etish.', 3);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'weekly', 'Haftalik P&L va Cash Flow', 'Haftalik foyda-zarar va pul oqimi holatini ko''rib chiqib direktsiyaga xabar berish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'weekly', 'Qarzdorlik nazorati', 'Haftalik qarzdorlar ro''yxati va undirilgan to''lovlarni jamlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'weekly', 'Xarajatlar hujjatlari', 'Haftalik barcha xarajatlar hujjatlarini tartibga keltirish va kiritish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'monthly', 'Oylik moliyaviy hisobot (P&L)', 'Oylik to''liq P&L, Cash Flow va byudjet bajarilishi hisobotini taqdim etish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'monthly', 'Oylik oylik maosh (payroll)', 'Xodimlar oyliklari va bonuslarini hisoblab vedomost tayyorlash.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('financist', 'monthly', 'Oylik byudjet rejasi', 'Kelgusi oy byudjeti va xarajatlar limitini belgilash.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('project_manager', 'daily', 'Loyihalar holatini yangilash', 'Har kuni faol loyihalar vazifalari holatini yangilab, bajarilish darajasi va to''siqlarni (blockers) aniqlash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('project_manager', 'daily', 'Kunlik standup', 'Jamoa bilan qisqa standup o''tkazib, bugungi asosiy vazifalar va mas''ullarni kelishish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('project_manager', 'daily', 'Deadline nazorati', 'Muddati yaqinlashgan vazifalarni tekshirib, mas''ul xodimlarga eslatma yuborish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('project_manager', 'weekly', 'Haftalik sprint rejasi', 'Haftalik sprint maqsadlari va vazifalar taqsimotini belgilash.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('project_manager', 'weekly', 'Haftalik progress hisoboti', 'Loyihalar progressi va risklar bo''yicha direktsiyaga hisobot berish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('project_manager', 'monthly', 'Oylik roadmap ko''rib chiqish', 'Oylik loyihalar roadmapini yangilab, maqsadlar va resurslarni muvofiqlashtirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('it_developer', 'daily', 'Tizimlar ishga tushishi', 'Har kuni CRM, LMS, sayt, kassa va internet tizimlarining to''g''ri ishlayotganini tekshirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('it_developer', 'daily', 'Texnik murojaatlar (tickets)', 'Kun davomida kelgan texnik muammolar va so''rovlarni ko''rib chiqib, ustuvorlik bo''yicha hal qilish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('it_developer', 'daily', 'Zaxira (backup) nazorati', 'Ma''lumotlar bazasi zaxirasi muvaffaqiyatli bajarilganini kunlik tekshirish.', 2);
insert into checklist_templates (role, cadence, title, detail, sort) values ('it_developer', 'weekly', 'Tizim yangilanishlari', 'Haftalik dasturiy yangilanishlar va xavfsizlik tekshiruvini bajarish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('it_developer', 'weekly', 'Ishlash va uptime tahlili', 'Tizimlar tezligi va uzilishlar (uptime) bo''yicha haftalik ko''rib chiqish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('it_developer', 'monthly', 'Oylik IT infratuzilma auditi', 'Oylik xavfsizlik, litsenziyalar va infratuzilma holatini tekshirish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('internship', 'daily', 'Kunlik topshiriqlar', 'Murabbiy bergan kunlik topshiriqlarni bajarish va bajarilish holatini xabar qilish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('internship', 'daily', 'Kuzatuv va o''rganish', 'Tajribali xodimlar ishini kuzatib, o''rgangan narsalarni yozib borish.', 1);
insert into checklist_templates (role, cadence, title, detail, sort) values ('internship', 'weekly', 'Haftalik o''rganish hisoboti', 'Hafta davomida o''rgangan ko''nikmalar bo''yicha murabbiyga hisobot berish.', 0);
insert into checklist_templates (role, cadence, title, detail, sort) values ('internship', 'monthly', 'Oylik rivojlanish suhbati', 'Oylik natijalar va keyingi o''rganish rejasi bo''yicha murabbiy bilan suhbat.', 0);
